"""
    Returns n counters after the increment and max operations coded in array.

    It iterates over array once and over the counters once, thus the time complexity is O(n + m)
  """
def solution(n: int, array: list[int]) -> list[int] {
    counters = [0] * n;
    max_count = 0;
    last_max_value = 0;
    for x in array {
        if x == n + 1 {
            last_max_value = max_count;
        } else {
            if counters[x - 1] < last_max_value {
                counters[x - 1] = last_max_value + 1;
            } else {
                counters[x - 1] += 1;
            }
            if counters[x - 1] > max_count {
                max_count = counters[x - 1];
            }
        }
    }
    return [max(i, last_max_value) for i in counters];
}

