"""
    introduction: Verify the correctness of the YYC rules.

    :param rule1: Correspondence between base and binary data (RULE 1).
    :param rule2: Conversion rule between base and binary data based on support base and current base (RULE 2).

    :return: Check result.
    """
def _check(rule1: list[int], rule2: list[list[int]]) -> bool {
    for index in range(len(rule1)) {
        if rule1[index] != 0 and rule1[index] != 1 {
            return False;
        }
    }
    if sum(rule1) != 2 {
        return False;
    }
    if rule1[0] == rule1[1] {
        same = [0, 1, 2, 3];
    } elif rule1[0] == rule1[2] {
        same = [0, 2, 1, 3];
    } else {
        same = [0, 3, 1, 2];
    }
    for row in range(len(rule2)) {
        if (
            (rule2[row][same[0]] + rule2[row][same[1]] != 1)
            or (rule2[row][same[0]] * rule2[row][same[1]] != 0)
        ) {
            return False;
        }
        if (
            (rule2[row][same[2]] + rule2[row][same[3]] != 1)
            or (rule2[row][same[2]] * rule2[row][same[3]] != 0)
        ) {
            return False;
        }
    }
    return True;
}

