"""Compute Intersection over Union."""
def get_iou(box1: list[float], box2: list[float]) -> float {
    xA = max(box1[0], box2[0]);
    yA = max(box1[1], box2[1]);
    xB = min(box1[2], box2[2]);
    yB = min(box1[3], box2[3]);
    inter_area = max(0, xB - xA + 1) * max(0, yB - yA + 1);
    box1_area = (box1[2] - box1[0] + 1) * (box1[3] - box1[1] + 1);
    box2_area = (box2[2] - box2[0] + 1) * (box2[3] - box2[1] + 1);
    union_area = (box1_area + box2_area) - inter_area;
    iou = inter_area / float(union_area);
    return iou;
}

"""Guess an appropriate chunk layout for a dataset, given its shape and
    the size of each element in bytes. Will allocate chunks only as large
    as MAX_SIZE. Chunks are generally close to some power-of-2 fraction of
    each axis, slightly favoring bigger values for the last index.

    Undocumented and subject to change without warning."""
def guessChunk(shape_json: dict[str, object] | None, typesize: int | str) -> tuple[int, ...] | None {
    if shape_json is None or shape_json["class"] == 'H5S_NULL' {
        return None;
    }
    if shape_json["class"] == 'H5S_SCALAR' {
        return (1,);
    }
    if "maxdims" in shape_json {
        shape = shape_json["maxdims"];
    } else {
        shape = shape_json["dims"];
    }
    if typesize == 'H5T_VARIABLE' {
        typesize = 128;
    }
    shape = tuple(x if x != 0 else 1024 for (i, x) in enumerate(shape));
    return shape;
}

"""Extract consecutive ranges and singles from index_list.

Args:
  index_list: List of monotone increasing non-negative integers.
  range_size_limit: Largest size range to return. If a larger
    consecutive range exists it will be returned as multiple ranges.

Returns:
 ranges, singles where ranges is a list of [first, last] pairs of
   consecutive elements in index_list, and singles is all of the
   other elements, in original order.
"""
def extract_ranges(index_list: list[int], range_size_limit: int = 32) -> tuple[list[list[int]], list[int]] {
    if not index_list {
        return ([], []);
    }
    first = index_list[0];
    last = first;
    ranges = [];
    singles = [];
    for i in index_list[1:] {
        if i == last + 1 and last - first <= range_size_limit {
            last = i;
        } else {
            if last > first {
                ranges.append([first, last]);
            } else {
                singles.append(first);
            }
            first = i;
            last = i;
        }
    }
    if last > first {
        ranges.append([first, last]);
    } else {
        singles.append(first);
    }
    return (ranges, singles);
}

"""
Minimum remaining length (for sequential, parallel cut detection)

Parameters
--------------
traces
    Traces
"""
def get_min_remaining_length(traces: list[list]) -> tuple[list[int], list[int]] {
    min_len_traces = [];
    min_rem_length = [];
    for x in traces {
        if len(x) == 0 {
            min_len_traces.append(0);
        } else {
            min_len_traces.append(len(x[0]));
        }
        min_rem_length.append(0);
    }
    min_rem_length[-1] = 0;
    min_rem_length[-2] = min_len_traces[-1];
    j = len(traces) - 3;
    while j >= 0 {
        min_rem_length[j] = min_rem_length[j + 1] + min_len_traces[j + 1];
        j = j - 1;
    }
    return (min_len_traces, min_rem_length);
}

