""" searches an element in a matrix where in every row, the values are increasing from left to
    right, but the last number in a row is smaller than the first number in the next row.
    The naive brute force solution scan all numbers and cost O(nm).  However, since the numbers are
    already sorted, the matrix can be viewed as a 1D sorted array.  The binary search algorithm is
    suitable. The efficience is O(logmn)."""
def searching_in_a_matrix(m1: list[list[int]], value: int) -> bool {
    rows = len(m1);
    cols = len(m1[0]);
    lo = 0;
    hi = rows * cols;
    while lo < hi {
        mid = (lo + hi) // 2;
        row = mid // cols;
        col = mid % cols;
        v = m1[row][col];
        if v == value {
            return True;
        } elif v > value {
            hi = mid;
        } else {
            lo = mid + 1;
        }
    }
    return False;
}

"""Command-line -> method call arg processing.

    - positional args:
            a b -> method('a', 'b')
    - intifying args:
            a 123 -> method('a', 123)
    - json loading args:
            a '["pi", 3.14, null]' -> method('a', ['pi', 3.14, None])
    - keyword args:
            a foo=bar -> method('a', foo='bar')
    - using more of the above
            1234 'extras=["r2"]'  -> method(1234, extras=["r2"])

    @param argv {list} Command line arg list. Defaults to `sys.argv`.
    @returns (<method-name>, <args>, <kwargs>)
    """
def _method_info_from_argv(argv: list[str] | None = None) -> tuple[str, list[any], dict[str, any]] {
    import json;
    import sys;
    if argv is None {
        argv = sys.argv;
    }
    (method_name, arg_strs) = (argv[1], argv[2:]);
    args: list[any] = [];
    kwargs: dict[str, any] = {};
    for s in arg_strs {
        if s.count('=') == 1 {
            (key, value) = s.split('=', 1);
        } else {
            (key, value) = (None, s);
        }
        try {
            value = json.loads(value);
        } except ValueError {
            ;
        }
        if key {
            kwargs[key] = value;
        } else {
            args.append(value);
        }
    }
    return (method_name, args, kwargs);
}

