"""
    The Rec.2020 12-bit transfer function.

    Parameters
    ----------
    v : float
        The normalized value to pass through the function.

    Returns
    -------
    float
        A converted value.
    """
def transfer_function_Rec2020_12bit_to_linear(v: float) -> float {
    a = 1.0993;
    b = 0.0181;
    d = 4.5;
    g = 1.0 / 0.45;
    if v < b * d {
        return v / d;
    }
    return pow((v + (a - 1)) / a, g);
}

