"""Removes duplicates from a sorted list"""
def RemoveDuplicate(Sortedlist: list[any]) -> list[any] {
    new_list = [];
    if not Sortedlist {
        return new_list;
    } else {
        prev = None;
        for element in Sortedlist {
            if element == prev {
                continue;
            } else {
                new_list.append(element);
                prev = element;
            }
        }
        return new_list;
    }
}

