"""
    Return True if the given integer is prime, False
    otherwise.

    >>> is_prime(1)
    False
    >>> is_prime(2)
    True
    >>> is_prime(3)
    True
    >>> is_prime(4)
    False
    >>> is_prime(9)
    False
    >>> is_prime(10)
    False
    """
def is_prime(n: int) -> bool {
    if n < 2 {
        return False;
    }
    if n == 2 {
        return True;
    }
    if n % 2 == 0 {
        return False;
    }
    for i in range(3, n) {
        if n % i == 0 {
            return False;
        }
    }
    return True;
}

