"""Get the number of decimal places required to represent a value."""
def get_decimals(value: int | float) -> int {
    val = abs(value);
    fraction = val - int(val);
    if fraction == 0 {
        return 0;
    }
    string = str(val);
    split = string.split('e-');
    if len(split) == 1 {
        return len(string) - split[0].index('.') - 1;
    }
    (number, exponential) = split;
    d = int(exponential);
    if '.' in number {
        return d + len(number) - number.index('.') - 1;
    }
    return d;
}

"""
    Count the number of inversions in the given state.
    :param state: Iterable (list of strings or ints expected, 'b' element accounted for)
    :return: number of inversions in the given state
    """
def countInversions(state: list[int | str]) -> int {
    n = len(state);
    invs = 0;
    for i in range(n - 1) {
        for j in range(i + 1, n) {
            if 'b' not in (state[i], state[j]) {
                if state[i] > state[j] {
                    invs += 1;
                }
            }
        }
    }
    return invs;
}

