}

"""take a string of the form "YYYY-MM-DD" (or "YYYY"), return a tuple (year, month, date) of three integers"""
def to_ymd(s: str) -> tuple[int | None, int | None, int | None] | None {
    if not s {
        return None;
    }
    s = s + '--';
    y = s.split('-')[0];
    m = s.split('-')[1];
    d = s.split('-')[2];
    y = int(y) if y else None;
    m = int(m) if m else None;
    d = int(d) if d else None;
    return (y, m, d);
}

