    """
def func_g(a: int, n: int, p: int, x_i: int) -> int {
    if x_i % 3 == 2 {
        return a;
    } elif x_i % 3 == 0 {
        return (2 * a) % n;
    } elif x_i % 3 == 1 {
        return (a + 1) % n;
    } else {
        print("[-] Something's wrong!");
        return -1;
    }
}

