"""Returns i + the ordinal indicator for the number.

Example: ordinal(3) => '3rd'
"""
def ordinal(i: int) -> str {
    i = int(i);
    if i % 100 in (11, 12, 13) {
        return '%sth' % i;
    }
    ord = 'th';
    test = i % 10;
    if test == 1 {
        ord = 'st';
    } elif test == 2 {
        ord = 'nd';
    } elif test == 3 {
        ord = 'rd';
    }
    return '%s%s' % (i, ord);
}

