"""How much does the range (start1, end1) overlap with (start2, end2).
    Looks strange, but algorithm is tight and tested.

    Args:
        start1: start of interval 1, in any unit
        end1: end of interval 1
        start2: start of interval 2
        end2: end of interval 2

    Returns:
        overlap of intervals in same units as supplied."""
def overlap(start1: float, end1: float, start2: float, end2: float) -> float {
    return max(
        max(end2 - start1, 0) - max(end2 - end1, 0) - max(start2 - start1, 0), 0
    );
}

import from typing { Iterator }

glob LEB128_LOW_MASK = 0x7F;
glob LEB128_CONT_BIT = 0x80;

"""Read variable length encoded 128 bits unsigned integer."""
def unsigned_leb128_decode(data: Iterator[int]) -> int {
    result = 0;
    shift = 0;
    while True {
        byte = next(data);
        result |= (byte & LEB128_LOW_MASK) << shift;
        if byte & LEB128_CONT_BIT == 0 {
            break;
        }
        shift += 7;
    }
    return result;
}

