"""
    Get frequency weighted intersection over union.

    Parameters
    ----------
    n : dict
        Confusion matrix which has integer keys 0, ..., nb_classes - 1;
        an entry n[i][j] is the count how often class i was classified as
        class j.

    Returns
    -------
    float
        frequency weighted iou (in [0, 1])

    Examples
    --------
    >>> n = {0: {0: 10, 1: 2}, 1: {0: 5, 1: 83}}
    >>> get_frequency_weighted_iou(n)
    0.8821437908496732
    """
def get_frequency_weighted_iou(n: dict[int, dict[int, int]]) -> float {
    k = len(n[0]);
    t = [sum([n[i][j] for j in range(k)]) for i in range(k)];
    a = sum(t) ** -1;
    b = sum(
        [
            (t[i] * n[i][i]) / (t[i] - n[i][i] + sum([n[j][i] for j in range(k)]))
            for i in range(k)
        ]
    );
    return a * b;
}

"""
