def rescale_score_by_abs(score: float, max_score: float, min_score: float) -> float | None {
    """
    rescale positive score to the range [0.5, 1.0], negative score to the range [0.0, 0.5],
    using the extremal scores max_score and min_score for normalization
    """
    if max_score > 0 and min_score < 0 {
        if max_score >= abs(min_score) {
            if score >= 0 {
                return 0.5 + 0.5 * (score / max_score);
            } else {
                return 0.5 - 0.5 * (abs(score) / max_score);
            }
        } elif score >= 0 {
            return 0.5 + 0.5 * (score / abs(min_score));
        } else {
            return 0.5 - 0.5 * (score / min_score);
        }
    } elif max_score > 0 and min_score >= 0 {
        if max_score == min_score {
            return 1.0;
        } else {
            return 0.5 + 0.5 * (score / max_score);
        }
    } elif max_score <= 0 and min_score < 0 {
        if max_score == min_score {
            return 0.0;
        } else {
            return 0.5 - 0.5 * (score / min_score);
        }
    }
}

def kelvin_to_rgb(K: int) -> tuple[float, float, float] {
    """converts color temperature in Kelvin to RGB values according to
    http://www.vendian.org/mncharity/dir3/blackbody/UnstableURLs/bbr_color.html"""
    table = {
        4000: (1.0, 0.6636, 0.3583),
        5000: (1.0, 0.7992, 0.6045),
        6000: (1.0, 0.9019, 0.8473),
        7000: (0.9337, 0.915, 1.0),
        8000: (0.7874, 0.8187, 1.0),
        9000: (0.6693, 0.7541, 1.0),
        0: (1, 1, 1)
    };
    return table[K];
}

