glob GIGA = 2 ** 30;
glob MEGA = 2 ** 20;
glob KILO = 2 ** 10;

"""Returns file size qualifier."""
def get_qual(fsize: int | float) -> tuple[float, str] {
    qual: str;
    if fsize > GIGA {
        fsize = fsize / GIGA;
        qual = 'Giga';
    } elif fsize > MEGA {
        fsize = fsize / MEGA;
        qual = 'Mega';
    } elif fsize > KILO {
        fsize = fsize / KILO;
        qual = 'Kilo';
    } else {
        qual = '';
    }
    fsize = round(fsize, 2);
    return (fsize, qual);
}

"""Prints a number of seconds in a terse, human-readable format.

Adapted from: https://gist.github.com/thatalextaylor/7408395
"""
def pretty_time_delta(seconds: int | float) -> str {
    seconds = int(seconds);
    (days, seconds) = divmod(seconds, 86400);
    (hours, seconds) = divmod(seconds, 3600);
    (minutes, seconds) = divmod(seconds, 60);
    if days > 0 {
        return '%dd%dh%dm%ds' % (days, hours, minutes, seconds);
    }
    if hours > 0 {
        return '%dh%dm%ds' % (hours, minutes, seconds);
    }
    if minutes > 0 {
        return '%dm%ds' % (minutes, seconds);
    }
    return '%ds' % (seconds,);
}

