"""N is length of arr."""
def searchsorted(arr: list[int], N: int, x: int) -> int {
    L = 0;
    R = N - 1;
    done = False;
    m = (L + R) // 2;
    while not done {
        if arr[m] < x {
            L = m + 1;
        } elif arr[m] > x {
            R = m - 1;
        } elif arr[m] == x {
            done = True;
        }
        m = (L + R) // 2;
        if L > R {
            done = True;
        }
    }
    return L;
}

"""Problem 9 - Special Pythagorean triplet"""
def problem9(solution: int) -> int {
    a = 1;
    while a <= solution / 3 {
        b = a + 1;
        while b <= solution / 2 {
            c = solution - (a + b);
            if c <= b {
                break;
            }
            if (a * a) + (b * b) == (c * c) {
                return a * b * c;
            }
            b += 1;
        }
        a += 1;
    }
    return -1;
}

