"""
A way to generate varying timeouts based on ranges.

gross_time: some integer between start and end
start: the start value of the range
end: the end value of the range
precision: the precision to use to generate the timeout
split_range: generate values from both ends
returns a timeout value to use
"""
def get_timeout(gross_time: int, start: int, end: int, precision: float, split_range: bool) -> float {
    if split_range {
        top_num = float(end) / precision;
        bottom_num = float(start) / precision;
        if gross_time % 2 == 0 {
            timeout = top_num - float(gross_time) / precision;
        } else {
            timeout = bottom_num + float(gross_time) / precision;
        }
    } else {
        timeout = float(gross_time) / precision;
    }
    return timeout;
}

