import from typing { Callable }

"""Approximate solution of f(x)=0 on interval [a,b] by the secant method."""
def secant(f: Callable[[float], float], a: float, b: float, n: int) -> float | None {
    if f(a) * f(b) >= 0 {
        print("Secant method fails.");
        return None;
    }
    a_n = a;
    b_n = b;
    for n in range(1, n + 1) {
        m_n = a_n - f(a_n) * (b_n - a_n) / (f(b_n) - f(a_n));
        f_m_n = f(m_n);
        if f(a_n) * f_m_n < 0 {
            a_n = a_n;
            b_n = m_n;
        } elif f(b_n) * f_m_n < 0 {
            a_n = m_n;
            b_n = b_n;
        } elif f_m_n == 0 {
            return m_n;
        } else {
            return None;
        }
    }
    return a_n - f(a_n) * (b_n - a_n) / (f(b_n) - f(a_n));
}

"""
Thresholds taken from https://en.wikipedia.org/wiki/Flesch%E2%80%93Kincaid_readability_tests
Returns a reading level and difficulty for a given flesch score.
"""
def get_reading_level_from_flesch(flesch_score: float) -> str {
    match flesch_score {
        case _ if flesch_score < 30:
            return "Very difficult to read";
        case _ if flesch_score < 50:
            return "Difficult to read";
        case _ if flesch_score < 60:
            return "Fairly difficult to read";
        case _ if flesch_score < 70:
            return "Plain English";
        case _ if flesch_score < 80:
            return "Fairly easy to read";
        case _ if flesch_score < 90:
            return "Easy to read";
        case _:
            return "Very easy to read";
    }
}

