    neighbor_lst = [];
    for i in range(-1, 2) {
        for j in range(-1, 2) {
            if 0 <= x + i < 4 {
                if 0 <= y + j < 4 {
                    if not i == j == 0 {
                        neighbor_lst.append((x + i, y + j));
