""" Naive PreOp algorithm """
def PreOpN(op: Callable, items: list) -> list {
    k = len(items);
    output = [None] * k;
    output[0] = items[0];
    for i in range(1, k) {
        output[i] = op(output[i - 1], items[i]);
    }
    return output;
}

