"""
    try to detect if a chandle stick fall in the pattern of a doji, long-shadow and hammer
    :daily_movement_minimum: default to 0.01 (1%)
    """
def long_tail_reversal(
    close: float,
    open: float,
    high: float,
    low: float,
    trend: str = 'up',
    daily_movement_minimum: float = 0.01
) -> bool {
    detected = False;
    mid_point_magnatude_scaling = 0.8;
    if abs(high - low) / open < daily_movement_minimum {
        return False;
    }
    if trend == 'up' {
        mid_point = (high - low) / 2.0 * mid_point_magnatude_scaling + low;
        if open >= mid_point and close >= mid_point {
            detected = True;
        }
    } else {
        mid_point = (high - low) / 2.0 * (1 + (1 - mid_point_magnatude_scaling)) + low;
        if open <= mid_point and close <= mid_point {
            detected = True;
        }
    }
    return detected;
}

"""
	survival_score = 80% * survival time score + 20% * win place score

	: type timeSurvived: int -- participant time survived
	: type duration: int  -- match duration time
	: type winPlace: int
	: rtype survival_score: int
	"""
def survival_score(timeSurvived: int, duration: int, winPlace: int) -> int {
    survival = (timeSurvived / duration) * 100;
    if winPlace == 1 {
        win_place = 100;
    } else {
        win_place = 100 - winPlace;
    }
    survival_score = int(survival * 0.8 + win_place * 0.2);
    if survival_score < 50 {
        survival_score = 50;
    }
    return survival_score;
}

