"""
    Calculate the Intersection over Union (IoU) of two bounding boxes.
    Parameters
    ----------
    bb1 : dict
        Keys: {'x1', 'x2', 'y1', 'y2'}
    bb2 : dict
        Keys: {'x1', 'x2', 'y1', 'y2'}
    Returns
    -------
    float
        in [0, 1]
    """
def get_iou(bb1: dict[str, float], bb2: dict[str, float]) -> float {
    assert bb1['x1'] <= bb1['x2'];
    assert bb1['y1'] <= bb1['y2'];
    assert bb2['x1'] <= bb2['x2'];
    assert bb2['y1'] <= bb2['y2'];
    x_left = max(bb1['x1'], bb2['x1']);
    y_top = max(bb1['y1'], bb2['y1']);
    x_right = min(bb1['x2'], bb2['x2']);
    y_bottom = min(bb1['y2'], bb2['y2']);
    if x_right < x_left or y_bottom < y_top {
        return 0.0;
    }
    intersection_area = (x_right - x_left) * (y_bottom - y_top);
    bb1_area = (bb1['x2'] - bb1['x1']) * (bb1['y2'] - bb1['y1']);
    bb2_area = (bb2['x2'] - bb2['x1']) * (bb2['y2'] - bb2['y1']);
    iou = intersection_area / float(bb1_area + bb2_area - intersection_area);
    assert iou >= 0.0;
    assert iou <= 1.0;
    return iou;
}

"""return a sorted copy of the input list x"""
def bubble_sort(x: list[int]) -> list[int] {
    L = x[:];
    swap = False;
    while not swap {
        swap = True;
        print(L);
        for i in range(1, len(L)) {
            if L[i] < L[i - 1] {
                swap = False;
                (L[i - 1], L[i]) = (L[i], L[i - 1]);
            }
        }
    }
    return L;
}

"""Taken from yum's rpmUtils.miscutils.py file
Pass in a standard style rpm fullname
Return a name, version, release, epoch, arch, e.g.::
foo-1.0-1.i386.rpm returns foo, 1.0, 1, i386
1:bar-9-123a.ia64.rpm returns bar, 9, 123a, 1, ia64
"""
def _rpm_split_filename(filename: str) -> tuple[str, str, str, str, str] {
    if filename[-4:] == '.rpm' {
        filename = filename[:-4];
    }
    arch_index = filename.rfind('.');
    arch = filename[arch_index + 1:];
    rel_index = filename[:arch_index].rfind('-');
    rel = filename[rel_index + 1:arch_index];
    ver_index = filename[:rel_index].rfind('-');
    ver = filename[ver_index + 1:rel_index];
    epoch_index = filename.find(':');
    if epoch_index == -1 {
        epoch = '';
    } else {
        epoch = filename[:epoch_index];
    }
    name = filename[epoch_index + 1:ver_index];
    return (name, ver, rel, epoch, arch);
}

"""Old-style dead zone scaling, required for similar drive behaviour."""
def dead_zone(controller_input: float, dead_zone: float) -> float {
    if controller_input <= dead_zone and controller_input >= -dead_zone {
        return 0;
    } elif controller_input > 0 {
        return (controller_input - dead_zone) / (1 - dead_zone);
    } else {
        return (-controller_input - dead_zone) / (dead_zone - 1);
    }
}

