"""set a bit in a bitstring, 0 = MSB"""
def set_bitstring_bit(bitstring: bytes, bitnum: int, valuetoset: bool) -> bytes {
    bytepos = bitnum >> 3;
    bitpos = 7 - (bitnum % 8);
    bytevalue = bitstring[bytepos];
    if valuetoset {
        if bytevalue & (2 ** bitpos) {
            return bitstring;
        } else {
            return (
                bitstring[:bytepos]
                + (bytevalue + (2 ** bitpos)).to_bytes(1, byteorder='big')
                + bitstring[bytepos + 1:]
            );
        }
    } elif bytevalue & (2 ** bitpos) {
        return (
            bitstring[:bytepos]
            + (bytevalue - (2 ** bitpos)).to_bytes(1, byteorder='big')
            + bitstring[bytepos + 1:]
        );
    } else {
        return bitstring;
    }
}

