def beaufort(n: float) -> str {
    s = '';
    if n < 0.3 {
        s = 'calm';
    } elif n < 1.6 {
        s = 'light air';
    } elif n < 3.4 {
        s = 'light breeze';
    } elif n < 5.5 {
        s = 'gentle breeze';
    } elif n < 8.0 {
        s = 'moderate breeze';
    } elif n < 10.8 {
        s = 'fresh breeze';
    } elif n < 13.9 {
        s = 'strong breeze';
    } elif n < 17.2 {
        s = 'high wind';
    } elif n < 20.8 {
        s = 'gale';
    } elif n < 24.5 {
        s = 'strong gale';
    } elif n < 28.5 {
        s = 'storm';
    } elif n < 32.7 {
        s = 'violent storm';
    } else {
        s = 'hurricane force';
    }
    return s;
}

"""Return list of params as params.

