    retval = "";
    for character in flag_code {
        if character == "S" {
            retval = retval + " SYN";
        } elif character == "P" {
            retval = retval + " PSH";
        } elif character == "F" {
            retval = retval + " FIN";
        } elif character == "C" {
            retval = retval + " CWR";
        } elif character == "R" {
            retval = retval + " RST";
        } elif character == "U" {
            retval = retval + " URG";
        } elif character == "E" {
            retval = retval + " ECE";
        } elif character == "A" {
            retval = retval + " ACK";
        } else {
            retval = character;
        }
    }
    retval = retval.strip();
    return retval;
}

