    if result_type == 'F' and pred != target {
        return True;
    }
    if result_type == 'TP' and pred == target and target == 1 {
        return True;
    }
    if result_type == 'FP' and pred != target and target == 0 {
        return True;
    }
    if result_type == 'TN' and pred == target and target == 0 {
