}

"""Remove empty entries in a nested list/dictionary of items,
    deep removing nested empty entries.
    """
def clean_empty(data: any) -> any {
    if isinstance(data, dict) {
        cleaned = {k: clean_empty(v) for (k, v) in data.items()};
        return {k: v for (k, v) in cleaned.items() if v};
    }
    if isinstance(data, list) {
        return [v for v in map(clean_empty, data) if v];
    }
    return data;
}

"""Return the complement of each nucleotide"""
def rev_seq(nuc: str, nuc_type: str = 'dna') -> str {
    if nuc == 'A' {
        if nuc_type == 'rna' {
            return 'U';
        } elif nuc_type == 'dna' {
            return 'T';
        } else {
            return 'T';
        }
    } elif nuc == 'T' {
        return 'A';
    } elif nuc == 'C' {
        return 'G';
    } elif nuc == 'U' {
        return 'A';
    } else {
        return 'C';
    }
}

