glob LEB128_BYTE_MASK = 0x7f;
glob LEB128_CONTINUATION_BIT = 0x80;

"""
Encode a number using LEB128 encoding (Zarith)
:param int value: the value to encode
:return: encoded value
:rtype: bytes
"""
def forge_nat(value: int) -> bytes {
    if value < 0 {
        raise ValueError('Value cannot be negative.');
    }
    buf = bytearray();
    more = True;
    while more {
        byte = value & LEB128_BYTE_MASK;
        value >>= 7;
        if value {
            byte |= LEB128_CONTINUATION_BIT;
        } else {
            more = False;
        }
        buf.append(byte);
    }
    return bytes(buf);
}

"""Clears the bit at offset k"""
