    }
    return min(2 * H / D, 10);
}

""" Given a list that may include duplicates, return a list of unique items

Returns a list of [(x,index)] for each 'x' in listOfItems,
where index is the number of times we've seen 'x' before.
"""
def augmentToBeUnique(listOfItems: list[object] | None) -> list[tuple[object, int]] {
    counts: dict[object, int] = {};
    output: list[tuple[object, int]] = [];
    if listOfItems is None {
        return [];
    }
    for x in listOfItems {
        counts[x] = counts.setdefault(x, 0) + 1;
        output.append((x, counts[x] - 1));
    }
    return output;
}

"""move blank space down on the board and return new state."""
def down(state: list[int]) -> list[int] | None {
    new_state = state[:];
    index = new_state.index(0);
    if index not in [6, 7, 8] {
        temp = new_state[index + 3];
        new_state[index + 3] = new_state[index];
        new_state[index] = temp;
        return new_state;
    } else {
        return None;
    }
}

