"""
        Center a molecule using equally weighted points

        Parameters
            numpoints: Number of points
            refcoords: List of reference coordinates, with each set
                       a list of form [x,y,z] (list)
        Returns
            refcenter: Center of the set of points (list)
            relcoords: Moved refcoords relative to refcenter (list)
    """
def center(numpoints: int, refcoords: list[list[float]]) -> tuple[list[float], list[list[float]]] {
    refcenter = [];
    relcoords = [];
    for i in range(3) {
        refcenter.append(0.0);
    }
    for i in range(numpoints) {
        refcenter[0] += refcoords[i][0];
        refcenter[1] += refcoords[i][1];
        refcenter[2] += refcoords[i][2];
    }
    for i in range(3) {
        refcenter[i] = refcenter[i] / numpoints;
    }
    for i in range(numpoints) {
        relcoords.append([]);
        relcoords[i].append(refcoords[i][0] - refcenter[0]);
        relcoords[i].append(refcoords[i][1] - refcenter[1]);
        relcoords[i].append(refcoords[i][2] - refcenter[2]);
    }
    return (refcenter, relcoords);
}

"""
    returns the second lowest value in a list of numbers

    Args:
        values: a list of floats

    Returns:
        the second lowst number in values
    """
def get_second_smallest(values: list[float]) -> float {
    (smallest, second_smallest) = (float("inf"), float("inf"));
    for value in values {
        if value <= smallest {
            (smallest, second_smallest) = (value, smallest);
        } elif value < second_smallest {
            second_smallest = value;
        }
    }
    return second_smallest;
}

"""
    Returns the ID name for the given ID number, spreadsheet-style, i.e. from a to z,
    then from aa to az, ba to bz, etc., until zz.
    """
def intToID(idnum: int, prefix: str) -> str {
    rid = '';
    while idnum > 0 {
        idnum -= 1;
        rid = chr((idnum % 26) + ord('a')) + rid;
        idnum = int(idnum / 26);
    }
    return prefix + rid;
}

"""
    Such as 11:27 or 21:42:39 or 1-20:21:50
    """
def parse_elapsed_time_string(dstr: str) -> int | None {
    dy = 0;
    hr = 0;
    mn = 0;
    sc = 0;
    sL = dstr.split('-', 1);
    if len(sL) == 1 {
        hms = dstr;
    } else {
        try {
            dy = int(sL[0]);
            hms = sL[1];
        } except Exception {
            return None;
        }
    }
    nL = hms.split(':');
    try {
        sc = int(nL[-1]);
        if sc < 0 or sc >= 60 {
            return None;
        }
    } except Exception {
        return None;
    }
    if len(nL) > 1 {
        try {
            mn = int(nL[-2]);
            if mn < 0 or mn >= 60 {
                return None;
            }
        } except Exception {
            return None;
        }
    }
    if len(nL) > 2 {
        try {
            hr = int(nL[-3]);
            if hr < 0 or hr > 24 {
                return None;
            }
        } except Exception {
            return None;
        }
    }
    return dy * 24 * 60 * 60 + hr * 60 * 60 + mn * 60 + sc;
}

