"""
    Returns reverse complement of seq, with
    any non-ACTG characters replaced with Ns

    """
def reverse_complement(seq: str) -> str {
    transform = {'A': 'T', 'T': 'A', 'C': 'G', 'G': 'C', 'N': 'N'};
    try {
        comp = [transform[e] for e in seq];
    } except KeyError {
        seq = [e if e in "ACTGN" else "N" for e in seq];
        comp = [transform[e] for e in seq];
    }
    rev_comp = comp[::-1];
    rev_comp_string = ''.join(rev_comp);
    return rev_comp_string;
}

"""N is length of arr
    """
def searchsorted(arr: list[int], x: int, N: int = -1) -> tuple[int, bool] {
    if N == -1 {
        N = len(arr);
    }
    low = 0;
    high = N - 1;
    done = False;
    eq = False;
    m = (low + high) // 2;
    while not done {
        xm = arr[m];
        if xm < x {
            low = m + 1;
        } elif xm > x {
            high = m - 1;
        } elif xm == x {
            low = m;
            eq = True;
            done = True;
        }
        m = (low + high) // 2;
        if low > high {
            done = True;
        }
    }
    return (low, eq);
}

