"""Given a number x, returns True if it is prime; otherwise returns False"""
def is_prime(x: int) -> bool {
    num_factors = 0;
    if `type(x) != int {
        return False;
    }
    for n in range(2, x + 1) {
        if x % n == 0 {
            num_factors += 1;
        }
    }
    if num_factors == 1 {
        return True;
    }
    return False;
}

