""" Search for a doi in a list of references.

    Args:
        references (Iterable): References to loop through.
        doi (str): DOI of work to search for.

    Returns:
        bool: True if doi is in any of the references, else False.
    """
def is_in_references(references: list[str], doi: str) -> bool {
    url_doi = doi.replace('/', '%2F');
    for reference in references {
        if url_doi in reference or doi in reference {
            return True;
        }
    }
    return False;
}

"""Formats time into mm:ss:xx"""
def format_time(seconds: float) -> str {
    (minutes, seconds) = divmod(seconds, 60);
    centi = "{:.2f}".format(seconds % 1)[1:];
    return "{:02d}:{:02d}{}".format(int(minutes), int(seconds), centi);
}

"""
    Calculate the CPU percentage for a process running in a particular
    scenario.

    :param results: Results to extract values from.
    :param process: Process name to calculate CPU usage for.
    """
def cpu_usage_for_process(results: list[dict], process: str) -> float | None {
    process_results = [
        r
        for r in results
        if r['metric']['type'] == 'cputime' and r['process'] == process
    ];
    cpu_values = sum(r['value'] for r in process_results);
    wallclock_values = sum(r['wallclock'] for r in process_results);
    if wallclock_values > 0 {
        return float(cpu_values) / wallclock_values;
    }
    return None;
}

"""
    Calculates the distance traveled given the initial velocity, acceleration, and time, Helper function to the distance
    function.

    :param initial_velocity: Integer initial velocity
    :param acceleration: Integer acceleration
    :param time: Integer time

    :return: Integer distance traveled
