"""Return None if n < 2; otherwise a list of booleans marking primality up to n
    if bool=True, else the list of prime numbers less than or equal to n.
    """
def series(n: int, bool: bool = False) -> list[bool] | list[int] | None {
    if n < 2 {
        return None;
    }
    prime = [True] * (n + 1);
    p = 2;
    while p * p <= n {
        if prime[p] == True {
            for i in range(p * 2, n + 1, p) {
                prime[i] = False;
            }
        }
        p += 1;
    }
    if bool {
        return prime;
    } else {
        return [i for i in range(2, n + 1) if prime[i]];
    }
}

