    count = 5;
    for (j, row) in enumerate(board) {
        for (k, n) in enumerate(row) {
            if n is True {
                count -= 1;
            }
        }
        if count < 1 {
            return True;
        } else {
            count = 5;
        }
    }
    count = 5;
    for j in range(5) {
        for k in range(5) {
            if board[k][j] is True {
                count -= 1;
            }
        }
        if count < 1 {
