"""Returns the neighboring indices for a given index
in a matrix of m x n shape.
"""
def neighbors(i: int, j: int, m: int, n: int) -> list[tuple[int, int]] {
    inbrs = [-1, 0, 1];
    if i == 0 {
        inbrs = [0, 1];
    }
    if i == m - 1 {
        inbrs = [-1, 0];
    }
    jnbrs = [-1, 0, 1];
    if j == 0 {
        jnbrs = [0, 1];
    }
    if j == n - 1 {
        jnbrs = [-1, 0];
    }
    nbrs = [];
    for delta_i in inbrs {
        for delta_j in jnbrs {
            if delta_i == delta_j == 0 {
                continue;
            } else {
                nbrs.append((i + delta_i, j + delta_j));
            }
        }
    }
    return nbrs;
}

