"""
    Recursive merge dictionaries.

    :param dict1: Base dictionary to merge.
    :param dict2: Dictionary to merge on top of base dictionary.
    :return: Merged dictionary
    """
def merge(dict1: dict, dict2: dict) -> dict {
    for (key, val) in dict1.items() {
        if isinstance(val, dict) {
            dict2_node = dict2.setdefault(key, {});
            merge(val, dict2_node);
        } elif key not in dict2 {
            dict2[key] = val;
        }
    }
    return dict2;
}

import from typing { Callable }

"""
    If a score function is provided, the element with the lowest score AND the score is returned.
    If not, the index of lowest element in the list is returned.
    If the list is empty, None is returned.
    """
def argmin(list: list[any], score_func: Callable[[any], float] | None = None) -> int | tuple[any, float] | None {
    if len(list) == 0 {
        return None;
    }
    scores = list if score_func is None else [score_func(e) for e in list];
    best_index = 0;
    best_score = scores[0];
    for (i, score) in enumerate(scores) {
        if score < best_score {
            best_index = i;
            best_score = score;
        }
    }
    if score_func is None {
        return best_index;
    }
    return (list[best_index], best_score);
}

""" Find the longest string that is a prefix of all the strings.
    """
def common_prefix(strings: list[str]) -> str {
    if not strings {
        return '';
    }
    prefix = strings[0];
    for s in strings {
        if len(s) < len(prefix) {
            prefix = prefix[:len(s)];
        }
        if not prefix {
            return '';
        }
        for i in range(len(prefix)) {
            if prefix[i] != s[i] {
                prefix = prefix[:i];
                break;
            }
        }
    }
    return prefix;
}

