"""
This function does intersection over union between two bounding boxes.
:param boxA: box x1 represented as [min_x1, min_y1, max_x1, max_y1]
:param boxB: box x2 represented as [min_x2, min_y2, max_x2, max_y2]
:return: iou: intersection over union - a number between 0 and 1
"""
def bb_intersection_over_union(boxA: list[float], boxB: list[float]) -> float {
    x_a = max(boxA[0], boxB[0]);
    y_a = max(boxA[1], boxB[1]);
    x_b = min(boxA[2], boxB[2]);
    y_b = min(boxA[3], boxB[3]);
    if x_a > x_b or y_a > y_b {
        return 0;
    } else {
        inter_area = (x_b - x_a + 1) * (y_b - y_a + 1);
        box_a_area = (boxA[2] - boxA[0] + 1) * (boxA[3] - boxA[1] + 1);
        box_b_area = (boxB[2] - boxB[0] + 1) * (boxB[3] - boxB[1] + 1);
        iou = inter_area / float(box_a_area + box_b_area - inter_area);
        return iou;
    }
}

