"""
Inverse of state2bin. Given an index `bin`, the number of bins `num_bins`,
and the limits on a single state dimension, returns the corresponding value
in the middle of the bin (the average of the discretizations around it).
"""
def bin2state(bin: int, num_bins: int, limits: list[float]) -> float {
    bin_width = (limits[1] - limits[0]) / num_bins;
    return bin * bin_width + bin_width / 2 + limits[0];
}

"""Computes the Levenshtein and restricted Damerau-Levenshtein distances
between two Unicode strings with given lengths using the Wagner-Fischer
algorithm. These distances are defined recursively: the distance between two
strings is the cost of adjusting the last one or two characters plus the
distance between the prefixes that exclude those characters. The matrix is
filled in iteratively to avoid redundant computation.
"""
def _levenshtein_compute(source: str, target: str, rd_flag: bool) -> int {
    s_range = range(len(source) + 1);
    t_range = range(len(target) + 1);
    matrix = [[i if j == 0 else j for j in t_range] for i in s_range];
    for i in s_range[1:] {
        for j in t_range[1:] {
            del_dist = matrix[i - 1][j] + 1;
            ins_dist = matrix[i][j - 1] + 1;
            sub_trans_cost = 0 if source[i - 1] == target[j - 1] else 1;
            sub_dist = matrix[i - 1][j - 1] + sub_trans_cost;
            matrix[i][j] = min(del_dist, ins_dist, sub_dist);
            if rd_flag and i > 1 and j > 1 and source[i - 1] == target[j - 2] and source[i - 2] == target[j - 1] {
                trans_dist = matrix[i - 2][j - 2] + sub_trans_cost;
                matrix[i][j] = min(matrix[i][j], trans_dist);
            }
        }
    }
    return matrix[len(source)][len(target)];
}

