"""Split an hdf path of the form path.hdf/group into the path and group parts."""
def split_hdf_path(fname: str, subgroup: str | None = None) -> tuple[str, str | None] {
    for suf in [".hdf", ".h5"] {
        (name, _, group) = fname.rpartition(suf);
        if not name {
            continue;
        }
        name += suf;
        if not group {
            return (name, subgroup);
        } elif group[0] == "/" {
            group = group[1:];
            if subgroup {
                group += "/" + subgroup;
            }
            return (name, group);
        }
    }
    raise ValueError("Not an hdf path");
}

