"""
    Search bands for those within range of the target average that have
    performed the minimum number of shows. Returns matching band names.
    """
def find_bands(
    bands: dict[str, list[float]], target_avg: tuple[float, int], target_range: float, min_shows: int
) -> list[str] {
    search_range = [target_avg[0] - target_range, target_avg[0] + target_range];
    lower_bound = search_range[0];
    upper_bound = search_range[1];
    noted_scores = target_avg[1];
    score_index = 1;
    in_range = lambda (avg: float) { avg >= lower_bound and avg <= upper_bound; };
    score_avg = lambda (scores: list[float], kept_scores: int) { (sum(scores) / len(scores))
        if len(scores) <= kept_scores
        else (sum(scores[0:kept_scores]) / kept_scores); };
    return `list(
        map(
            lambda (name: tuple[str, list[float]]) { name[0]; },
            `list(
                filter(
                    lambda (band: tuple[str, list[float]]) { in_range(
                        score_avg(band[score_index], noted_scores)
                    ); },
                    filter(
                        lambda (band: tuple[str, list[float]]) { len(band[score_index]) >= min_shows; },
                        `list(bands.items())
                    )
                )
            )
        )
    );
}

"""Calculate the resulting output shape for an image layer with the specified options."""
def image_output_size(
    input_shape: tuple[int, int, int, int], size: tuple[int, ...], stride: tuple[int, int], padding: str
) -> tuple[int, int, int, int] {
    if len(size) > 2 and input_shape[3] != size[2] {
        print("Matrix size incompatible!");
    }
    height = size[0];
    width = size[1];
    out_depth = size[3] if len(size) > 2 else int(input_shape[3]);
    input_height = input_shape[1];
    input_width = input_shape[2];
    if padding == "VALID" {
        input_height -= height - 1;
        input_width -= width - 1;
    }
    return (
        int(input_shape[0]),
        (input_height + stride[0] - 1) // stride[0],
        (input_width + stride[1] - 1) // stride[1],
        out_depth
    );
}

