    "ANSYSEMSV_ROOT211"
    """
def env_value_student(input_version: str) -> str {
    version = int(input_version[2:4]);
    release = int(input_version[5]);
    if version < 20 {
        if release < 3 {
            version -= 1;
        } else {
            release -= 2;
        }
    }
    v_key = "ANSYSEMSV_ROOT{0}{1}".format(version, release);
    return v_key;
}

"""Ensures that the value is a list.
        If it is not a list, it creates a new list with `value` as an item.

    Args:
        value (object): A list or something else.
        return_empty_list_if_none (bool, optional): When True (default), None you passed as `value`
            will be converted to a empty list (i.e., `[]`). When False, None will be converted to
            a list that has an None (i.e., `[None]`). Defaults to True.
        convert_tuple_to_list (bool, optional): When True (default), a tuple you passed as `value`
            will be converted to a list. When False, a tuple will be unconverted
            (i.e., returning a tuple object that was passed as `value`). Defaults to True.
    Returns:
        list: A list. When `value` is a tuple and `convert_tuple_to_list` is False, a tuple.
    """
def listify(
    value: any, return_empty_list_if_none: bool = True, convert_tuple_to_list: bool = True
) -> list {
    if not isinstance(value, list) {
        if value is None and return_empty_list_if_none {
            value = [];
        } elif isinstance(value, tuple) and convert_tuple_to_list {
            value = list(value);
        } else {
            value = [value];
        }
    }
    return value;
}

"""Return all coordinates in the column of (col, row) as a list.

    Args:
        row (int): The row of the field.
        col (int): The column of the field.
        width (int): The width of the sudoku.
        height (int): The height of the sudoku.
        include (bool): Whether or not to include (row, col).

    Returns:
        list of (int, int): list of pairs (row, column) of all fields in
                            the same column.
    """
def column_of(
    row: int, col: int, width: int = 3, height: int = 3, include: bool = True
) -> list[tuple[int, int]] {
    return [
        (i, col)
        for i in range(width * height)
        if include or i != row
    ];
}

