def score_distance(x: float) -> float {
    a = 10;
    b = 0.5;
    s = 0.2;
    g = (0.18 * x) + s;
    f = ((1 / (b * g) ** 2) - (a / (b * g))) * 0.1 * (1 - x) / a;
    return min(1, -4.82 * f);
}

