import from typing { Callable }

"""Return the padding needed to extend a message to a multiple of group_len
    in length.

    fillvalue can be a function or a literal value. If a function, it is called
    once for each padded character. Use this with fillvalue=random_english_letter
    to pad a message with random letters.
    """
def pad(message_len: int, group_len: int, fillvalue: str | Callable[[], str]) -> str {
    padding_length = group_len - message_len % group_len;
    if padding_length == group_len {
        padding_length = 0;
    }
    padding = '';
    if callable(fillvalue) {
        for i in range(padding_length) {
            padding += fillvalue();
        }
    } else {
        padding += fillvalue * padding_length;
    }
    return padding;
}

"""Kendall distance with penalty p between two partial rank lists (lists with ties).
This could be sped up with more efficient computation of the size of the sets R1,
R2, and D. I normalize the distance by dividing by k*(k-1)/2."""
def partial_kendall(s1: list[float], s2: list[float], p: float = 0.5) -> float {
    cardD = 0;
    cardR1 = 0;
    cardR2 = 0;
    k = len(s1);
    for i in range(len(s1)) {
        for j in range(len(s2)) {
            if s1[i] < s1[j] and s2[i] > s2[j] {
                cardD += 1;
            } elif s1[i] == s1[j] and s2[i] != s2[j] {
                cardR1 += 1;
            } elif s2[i] == s2[j] and s1[i] != s1[j] {
                cardR2 += 1;
            }
        }
    }
    return (2 / (k * (k - 1))) * (cardD + p * (cardR1 + cardR2));
}

"""Recursively steps down the children of an event to calculate the number
of children.

Args:
  event (json): Json representing the current event.

Returns:
  The number of children of the current event."""
def _count_number_of_children_recursively(event: dict[str, object]) -> int {
    if len(event['children']) == 0 {
        return 0;
    }
    children = 0;
    for child in event['children'] {
        children += 1 + _count_number_of_children_recursively(child);
    }
    return children;
}

