"""Counts the number of occurrences of a given bigram in a sequence."""
def count_bigram(sequence: str, first: str, second: str) -> int {
    count = 0;
    cmp = False;
    for char in sequence {
        if cmp is True {
            cmp = False;
            if char == second {
                count += 1;
            }
        }
        if char == first {
            cmp = True;
        }
    }
    return count;
}

