    }
    return cardinals;
}

import from typing { Callable }

"""Python's 'in' keyword performs a linear search on arrays.
    Given the circumstances of storing sorted arrays, it's better
    for Nyx to use a binary search.

    Arguments:
    key - filter for objects in the array
    start - 0-indexed starting marker on the array to search
    end - exclusive ending marker on the array to search
    """
def binary_search(
    array: list[float] | None,
    query: float,
    key: Callable = lambda (a: float) { a; },
    start: int = 0,
    end: int = -1
) -> float | None {
    if array is None or len(array) == 0 {
        return None;
    }
    if end == -1 {
        end = len(array);
    } elif start >= end {
        return None;
    }
    mid = int(start + (end - start) / 2);
    compare_to = key(array[mid]);
    if query < compare_to {
        return binary_search(array, query, key, start, mid);
    } elif query > compare_to {
        return binary_search(array, query, key, mid + 1, end);
    } else {
        return array[mid];
    }
}

"""Returns a tuple of the velocities resulting from a perfectly
    elastic collision between masses m1 traveling at v1 and m2
    traveling at v2.  This simultaneously conserves momentum and energy."""
def Elastic(m1: float, m2: float, v1: float, v2: float) -> tuple[float, float] {
    vp2 = (m2 * v2 + m1 * (2.0 * v1 - v2)) / (m1 + m2);
    vp1 = vp2 + v2 - v1;
    return (vp1, vp2);
}

"""Computes an approximation for the expected value of Z_right^eF (right elegible first)
    for the right subproblem using expression (53b) in Corollary 26."""
def func_right_elegible_first(
    k_idx: int, k_right: float, s_right: float, cap_right_closed: int, closed_ZG_right: float
) -> float {
    mu = k_idx + 1;
    lamb = mu / 2;
    k_0 = k_right;
    s_0 = s_right;
    kp = cap_right_closed;
    closed_EF_right = k_0 * (kp - 2 * s_0 - 1) * (1 - (1 - k_0 / kp) ** (lamb - s_0)) / 4;
    closed_EF_right = closed_EF_right - kp * (1 - k_0 / kp) * (1 - (1 + (kp - s_0 - 1) * k_0 / kp) * (1 - k_0 / kp) ** (lamb - s_0 + 1)) / (4 * k_0);
    closed_EF_right = closed_EF_right + closed_ZG_right;
    return closed_EF_right;
}

