"""prime: calclates whether or not a number is prime
    Args:
    	num (int): Number to be evaluated as prime
    Returns:
    	bool: True if the number is prime, False otherwise
    Note: prime() is mostly for internal use, for a more user User-friendly version,
    see prime_out()
    """
def prime(num: int) -> bool {
    count = num - 1;
    def remain(div: int) -> bool {
        ans = num % div;
        if ans == 0 {
            return True;
        } else {
            return False;
        }
    }
    while count > 1 {
        if remain(count) {
            return False;
        } else {
            count = count - 1;
        }
    }
    return True;
}

