"""
Mirror an action, swapping left/right.
"""
def mirror_action(act: int) -> int {
    direction = (act % 18) // 6;
    act -= direction * 6;
    if direction == 1 {
        direction = 2;
    } elif direction == 2 {
        direction = 1;
    }
    act += direction * 6;
    return act;
}

"""Return the dict value for the given ordered keys.

Args:
    dct (dict): the dictionary that will be consulted.
    *keys: positional arguments which contains the key path to the
      wanted value.
    **kwargs:
      default -> If any key is missing, default will be returned.

Returns:
    the dictionary value for the given ordered keys.
"""
def safe_get(dct: dict[str, any], *keys: str | int, **kwargs: any) -> any {
    default_value = kwargs.get("default");
    for key in keys {
        try {
            dct = dct[key];
        } except (KeyError, IndexError) {
            return default_value;
        }
    }
    return dct;
}

