    dna (str): DNA string (whose alphabet contains the symbols 'A', 'C', 'G', and 'T').

Returns:
    str: rna where 'T' is replaced by 'U'.
"""
def dna_to_rna(dna: str) -> str {
    rna = dna.replace("T", "U");
    return rna;
}

"""
Parameters
----------
SEG_label : list
    label list.

Returns
-------
count_list : array
"""
def count_label(SEG_label: list[str]) -> list[int] {
    (N, S, V, F, Q) = (0, 0, 0, 0, 0);
    for label in SEG_label {
        N += label.count('N');
        S += label.count('S');
        V += label.count('V');
        F += label.count('F');
        Q += label.count('Q');
    }
    count_list = [N, S, V, F, Q];
    return count_list;
}

