""" Tries and creates pythonic name from c names """
def pythonic(name: str) -> str {
    name = str(name);
    to_lower = lambda (x: str) { x if x == x.lower() else "_" + x.lower() };
    return name[0].lower() + ''.join([to_lower(u) for u in name[1:]]);
}

"""Remove everything found between instances of start_string and end_string.

  Replace each such instance with replace_fn(removed_text)

  e.g. _find_and_replace("the [[fat]] cat [[sat]]", "[[", "]]", lambda x: x)
    = "the fat cat sat"

  Args:
    text: a unicode string
    start_string: a unicode string
    end_string: a unicode string
    replace_fn: a unary function from unicode string to unicode string

  Returns:
    a string
  """
def _find_and_replace(
    text: str, start_string: str, end_string: str, replace_fn: any
) -> str {
    ret = "";
    current_pos = 0;
    while True {
        start_pos = text.find(start_string, current_pos);
        if start_pos == -1 {
            ret += text[current_pos:];
            break;
        }
        ret += text[current_pos:start_pos];
        end_pos = text.find(end_string, start_pos + len(start_string));
        if end_pos == -1 {
            break;
        }
        ret += replace_fn(text[start_pos + len(start_string):end_pos]);
        current_pos = end_pos + len(end_string);
    }
    return ret;
}

"""rgb to 8-color pallete"""
def encode_color(rgb: tuple[int, int, int]) -> int | None {
    r = "1" if rgb[0] > 127 else "0";
    g = "1" if rgb[1] > 127 else "0";
    b = "1" if rgb[2] > 127 else "0";
    for i in range(8) {
        if r + g + b == format(i, '03b') {
            return i;
        }
    }
}

