"""Extracts the semantic version number from a version string
    Args:
      bazel_version: the version string that begins with the semantic version
        e.g. "1.2.3rc1 abc1234" where "abc1234" is a commit hash.
    Returns:
      The semantic version string, like "1.2.3".
    """
def _extract_version_number(bazel_version: str) -> str {
    for (i, c) in enumerate(bazel_version) {
        if not (c.isdigit() or c == ".") {
            return bazel_version[:i];
        }
    }
    return bazel_version;
}

def cpu_statistics(last: list[tuple[float, float]], ref: list[tuple[float, float]]) -> list[float] {
    """ Return the CPU loading for all the processors between last and ref measures.
    The average on all processors is inserted in front of the list. """
    cpu = [];
    for (l, r) in zip(last, ref) {
        work = l[0] - r[0];
        idle = l[1] - r[1];
        total = work + idle;
        cpu.append((100.0 * work / total) if total else 0);
    }
    return cpu;
}

def YDbDrtoYUV(Y: float, Db: float, Dr: float) -> tuple[float, float, float] {
    """ convert RGB to YUV color
    :param Y: Y value (0;1)
    :param Db: Db value (-1.333-1.333)
    :param Dr: Dr value (-1.333-1.333)
    :return: YUV (PAL) tuple (Y0;1 U-0.436-0.436 V-0.615-0.615) """
    U = Db / 3.059;
    V = Dr / -2.169;
    return (Y, U, V);
}

def calc_vol(t: float, env: list[list[float]]) -> float {
    """Calculate volume at time t given envelope env.

    envelope is a list of [time, volume] points; time is measured in samples;
    envelope should be sorted by time.
    """
    if len(env) == 0 {
        return 1.0;
    }
    if len(env) == 1 {
        return env[0][1];
    }
    n = 0;
    while n < len(env) and env[n][0] < t {
        n += 1;
    }
    if n == 0 {
        return env[0][1];
    }
    if n == len(env) {
        return env[-1][1];
    }
    f = float(t - env[n - 1][0]) / (env[n][0] - env[n - 1][0]);
    return env[n - 1][1] * (1.0 - f) + env[n][1] * f;
}

def max_dict(dicts: list[dict[str, int]]) -> dict[str, int] {
    """Merge dicts whose values are int.

    If a key is present in multiple dicts, choose the max.
    """
    ret = {};
    for cur_dict in dicts {
        for (key, value) in cur_dict.items() {
            ret[key] = max(d.get(key, 0) for d in dicts);
        }
    }
    return ret;
}

