def permissions_string(permissions: list[str] | None, known_permissions: set[str]) -> str {
    """Return a comma separated string of permission changes.

    permissions: A list of strings, or None. These strings can exclusively
    contain + or - prefixes, or contain no prefixes at all. When prefixed,
    the resulting string will simply be the joining of these inputs. When
    not prefixed, all permissions are considered to be additions, and all
    permissions in known_permissions that aren't provided are considered
    removals. When None, the result is '+all'.
    known_permissions: A set of strings representing the available
    permissions.
    """
    to_set = [];
    if permissions is None {
        to_set = ['+all'];
    } else {
        to_set = ['-all'];
        omitted = sorted(known_permissions - set(permissions));
        to_set.extend('-{}'.format(x) for x in omitted);
        to_set.extend('+{}'.format(x) for x in permissions);
    }
    return ','.join(to_set);
}

def _DivideAndCeil(dividend: int, divisor: int) -> int {
    """Returns ceil(dividend / divisor), taking care to avoid the pitfalls of
     floating point arithmetic that could otherwise yield the wrong result
     for large numbers.
    """
    quotient = dividend // divisor;
    if dividend % divisor != 0 {
        quotient += 1;
    }
    return quotient;
}

def prime_sieve(upper: int, lower: int = 2) -> list[int] {
    """Returns a list of primes from 2 to 'upper'"""
    if lower < 2 {
        raise ValueError("Lower bound cannot be lower than 2");
    }
    prime_list = list(range(lower, upper));
    index = 0;
    while True {
        try {
            prime = prime_list[index];
            for i in prime_list[index + 1:] {
                if i % prime == 0 {
                    prime_list.remove(i);
                }
            }
        } except IndexError {
            break;
        }
        index += 1;
    }
    return prime_list;
}

