"""
  Get only the variables required to netcdf2d

  Parameters
  ----------
  obj:object
  dimensions=list,['nnode','ntime']

  Notes
  -----
  idimensions=['inode','itime']

  """
def cleanObject(obj: dict, dimensions: list[str]) -> dict {
    if not ('variable' in obj) {
        raise Exception("Add {} to the default parameter object".format('variable'));
    }
    _obj = {};
    idimensions = ["{}{}".format('i', dimension[1:]) for dimension in dimensions];
    for name in idimensions {
        if name in obj {
            _obj[name] = obj[name];
        }
    }
    _obj['variable'] = obj['variable'];
    return _obj;
}

"""
    contoh
    >>> bubble_sort([0, 5, 2, 3, 2])
    [0, 2, 2, 3, 5]
    >>> bubble_sort([0, 5, 2, 3, 2]) == sorted([0, 5, 2, 3, 2])
    True
    """
def bubble_sort(collection: list[int]) -> list[int] {
    panjang = len(collection);
    for i in range(panjang - 1) {
        swap = False;
        for j in range(panjang - 1 - i) {
            if collection[j] > collection[j + 1] {
                swap = True;
                (collection[j], collection[j + 1]) = (
                    collection[j + 1],
                    collection[j]
                );
            }
        }
        if not swap {
            break;
        }
    }
    return collection;
}

"""Parses the module name from a "main_is" attribute.

    The attribute may be either Foo.Bar or Foo.Bar.baz.

    Args:
      main_is: A string, the main_is attribute

    Returns:
      A string, a valid Haskell module name.
    """
def _get_main_is_module(main_is: str) -> str {
    components = main_is.split(".");
    if components and components[-1] and components[-1][0:1].islower() {
        return ".".join(components[:-1]);
    } else {
        return main_is;
    }
}

"""assumes a_list is a list,
    assumes index1 is an int representing the index of one of the two values to be swaped
    assumes index1 is an int representing the index of one of the two values to be swaped
    does not modify the inputed list
    returns a list, equivalent to a_list with index1 and index2 swapped
    e.g. swap(['a','b','c'], 0, 2) -> ['c','b','a']
    """
def swap(a_list: list[str], index1: int, index2: int) -> list[str] {
    b_list = a_list.copy();
    b_list[index1] = a_list[index2];
    b_list[index2] = a_list[index1];
    return b_list;
}

"""Make a string key out of many criteria."""
def make_key(*criteria: object) -> str {
    parts = [];
    for criterion in criteria {
        if criterion is None {
            continue;
        }
        criterion = str(criterion);
        criterion = criterion.replace(":", "#");
        parts.append(criterion);
    }
    return ":".join(parts);
}

